descriptions.zh:
本接口与[BatchPutKv](~~2850203~~)的功能一样，只是允许上传更大请求体。当请求体较小时推荐直接使用[BatchPutKv](~~2850203~~)接口，从而减少服务端处理时间。本接口需要使用SDK进行调用。以golang SDK为例，需要使用BatchPutKvWithHighCapacityAdvance函数进行调用。
```
func TestBatchPutKvWithHighCapacity() error {
	// 配置初始化
	cfg := new(openapi.Config)
	cfg.SetAccessKeyId("xxxxxxxxx")
	cfg.SetAccessKeySecret("xxxxxxxxxx")
	cli, err := NewClient(cfg)
	if err != nil {
		return err
	}
	runtime := &util.RuntimeOptions{}

	// 构造待批量上传的键值对请求
	namespace := "test_batch_put"
	numKv := 10000
	kvList := make([]*BatchPutKvRequestKvList, numKv)
	test_value := strings.Repeat("a", 10*1024)
	for i := 0; i < numKv; i++ {
		key := fmt.Sprintf("test_key_%d", i)
		value := test_value
		kvList[i] = &BatchPutKvRequestKvList{
			Key:   &key,
			Value: &value,
		}
	}
	rawReq := BatchPutKvRequest{
		Namespace: &namespace,
		KvList:    kvList,
	}

	payload, err := json.Marshal(rawReq)
	if err != nil {
		return err
	}

	// 如果payload大于2M，则调用大容量接口进行上传
	reqHighCapacity := BatchPutKvWithHighCapacityAdvanceRequest{
		Namespace: &namespace,
		UrlObject: bytes.NewReader(payload),
	}
	resp, err := cli.BatchPutKvWithHighCapacityAdvance(&reqHighCapacity, runtime)
	if err != nil {
		return err
	}
	return nil
}

descriptions.en:
This operation provides the same functionality as [BatchPutKv](~~2850203~~), but allows larger request bodies. If the request body is small, use the [BatchPutKv](~~2850203~~) operation to reduce server-side processing time. This operation must be called by using an SDK. For example, when using the Golang SDK, call the BatchPutKvWithHighCapacityAdvance function.
```
func TestBatchPutKvWithHighCapacity() error {
	// Initialize the configuration
	cfg := new(openapi.Config)
	cfg.SetAccessKeyId("xxxxxxxxx")
	cfg.SetAccessKeySecret("xxxxxxxxxx")
	cli, err := NewClient(cfg)
	if err != nil {
		return err
	}
	runtime := &util.RuntimeOptions{}.

	// Construct the key-value pairs for batch upload
	namespace := "test_batch_put"
	numKv := 10000
	kvList := make([]*BatchPutKvRequestKvList, numKv)
	test_value := strings.Repeat("a", 10*1024)
	for i := 0; i < numKv; i++ {
		key := fmt.Sprintf("test_key_%d", i)
		value := test_value
		kvList[i] = &BatchPutKvRequestKvList{
			Key:   &key,
			Value: &value,
		}
	}
	rawReq := BatchPutKvRequest{
		Namespace: &namespace,
		KvList:    kvList,
	}.

	payload, err := json.Marshal(rawReq)
	if err != nil {
		return err
	}.

	// If the payload is larger than 2 MB, call the high-capacity operation to upload it
	reqHighCapacity := BatchPutKvWithHighCapacityAdvanceRequest{
		Namespace: &namespace,
		UrlObject: bytes.NewReader(payload),
	}
	resp, err := cli.BatchPutKvWithHighCapacityAdvance(&reqHighCapacity, runtime)
	if err != nil {
		return err
	}
	return nil
}.
